package com.company.platform.inventory.domain;
import java.math.BigDecimal;import java.time.*;import java.util.UUID;
public final class InventoryReservation{public enum Status{CREATED,ACTIVE,RELEASED,CONSUMED,EXPIRED}private final UUID id,tenantId,orderId,inventoryId;private final BigDecimal quantity;private final Instant expirationDate,createdAt;private Status status;private InventoryReservation(UUID id,UUID t,UUID o,UUID i,BigDecimal q,Status s,Instant e,Instant c){if(t==null||o==null||i==null||q==null||q.signum()<=0||e==null)throw new IllegalArgumentException("invalid reservation");this.id=id==null?UUID.randomUUID():id;tenantId=t;orderId=o;inventoryId=i;quantity=q;status=s==null?Status.CREATED:s;expirationDate=e;createdAt=c==null?Instant.now():c;}public static InventoryReservation create(UUID t,UUID o,UUID i,BigDecimal q,Instant e){return new InventoryReservation(null,t,o,i,q,null,e,null);}public void activate(){if(status!=Status.CREATED)throw new IllegalStateException("invalid reservation activation");status=Status.ACTIVE;}public void release(){if(status!=Status.ACTIVE)throw new IllegalStateException("invalid reservation release");status=Status.RELEASED;}public void consume(){if(status!=Status.ACTIVE)throw new IllegalStateException("invalid reservation consume");status=Status.CONSUMED;}public void expire(){if(status!=Status.ACTIVE||Instant.now().isBefore(expirationDate))throw new IllegalStateException("reservation is not expired");status=Status.EXPIRED;}public UUID id(){return id;}public UUID tenantId(){return tenantId;}public UUID orderId(){return orderId;}public UUID inventoryId(){return inventoryId;}public BigDecimal quantity(){return quantity;}public Status status(){return status;}public Instant expirationDate(){return expirationDate;}public Instant createdAt(){return createdAt;}}
